#!/usr/bin/env -S uv run --script
# AGENT INSTRUCTIONS: If editing the file, ensure that your model name is included here.
# Generated by Anthropic Claude-Opus-5 via Claude Code.
# Generates downscaled twins of the site's demo GIFs and images, driven by
# scaled-assets.yml, for embedding on sites that can't resize images themselves.
